function entrar(fila, nome) {
  if (!fila.includes(nome)) {
    fila.push(nome);
  }
  return fila.indexOf(nome) + 1;
}

function sair(fila, nome) {
  const i = fila.indexOf(nome);
  if (i === -1) {
    return false;
  }
  fila.splice(i, 1);
  return true;
}

const fila = ["Ana", "Bia"];
