function tempoTotal(voltas) {
  return voltas.reduce((soma, t) => soma + t, 0);
}

function primeiraVoltaRapida(voltas, limite) {
  return voltas.find((t) => t < limite);
}

function avaliarCorrida(voltas, limite) {
  if (voltas.every((t) => t < limite)) {
    return "perfeita";
  }
  if (voltas.some((t) => t < limite)) {
    return "boa";
  }
  return "lenta";
}

