function media(notas) {
  if (notas.length === 0) {
    return 0;
  }
  const soma = notas.reduce((total, nota) => total + nota, 0);
  return soma / notas.length;
}

function aprovados(turma) {
  return turma
    .filter((aluno) => media(aluno[1]) >= 7)
    .map((aluno) => aluno[0]);
}

function situacao(m) {
  if (m >= 7) {
    return "aprovado";
  }
  if (m >= 5) {
    return "recuperação";
  }
  return "reprovado";
}

function boletim(turma) {
  return [...turma]
    .sort((a, b) => media(b[1]) - media(a[1]))
    .map((aluno) => {
      const m = media(aluno[1]);
      return `${aluno[0]}: ${m.toFixed(1)} (${situacao(m)})`;
    });
}

const turma = [
  ["Ana", [8, 9, 7]],
  ["Caio", [5, 4, 6]],
  ["Bia", [10, 9, 9.5]],
  ["Duda", [7, 6, 8]],
];
